/** Real TLS and disposable PostgreSQL. Private addresses/trust are possible only through the existing test constructor. */
@SpringBootTest(properties={"bridgeops.auth.enabled=true","bridgeops.auth.origin=https://bridgeops.invalid","bridgeops.auth.issuer=rest-workflow","bridgeops.auth.key-id=rest-workflow","bridgeops.executions.worker.enabled=false","bridgeops.integrations.rest.allowed-hosts=api.example.com"})
@Testcontainers
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class RestWorkflowIT {
    static final TestAuthMaterial keys=new TestAuthMaterial();static final Path encryptionKey=encryptionKey();
    static Path encryptionKey(){try{Path file=keys.directory.resolve("local-v1.key");byte[] bytes=new byte[32];new java.security.SecureRandom().nextBytes(bytes);Files.write(file,bytes);Arrays.fill(bytes,(byte)0);if(Files.getFileStore(file).supportsFileAttributeView("posix"))Files.setPosixFilePermissions(file,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));return file;}catch(Exception unavailable){throw new ExceptionInInitializerError(unavailable);}}
    static final AtomicInteger requests=new AtomicInteger();static volatile int status;static volatile String retryAfter;static volatile boolean drop;static volatile Runnable beforeCall,afterCall;static volatile String receivedAuthorization,receivedKey,receivedBody;
    static final RestTransport provider=provider();
    static RestTransport provider(){try{
        RestTransportTest.tlsFixture();RestTransportTest.server.createContext("/workflow",exchange->{requests.incrementAndGet();receivedAuthorization=exchange.getRequestHeaders().getFirst("Authorization");receivedKey=exchange.getRequestHeaders().getFirst("Idempotency-Key");receivedBody=new String(exchange.getRequestBody().readNBytes(4097),StandardCharsets.UTF_8);if(drop){exchange.close();return;}byte[] body="{\"message\":\"controlled-result\",\"ignoredSecret\":\"not-projected\"}".getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json");if(retryAfter!=null)exchange.getResponseHeaders().set("Retry-After",retryAfter);exchange.sendResponseHeaders(status==0?200:status,body.length);try(var output=exchange.getResponseBody()){output.write(body);}});
        var dns=new DnsResolver(){public InetAddress[] resolve(String host){return new InetAddress[]{InetAddress.getLoopbackAddress()};}public String resolveCanonicalHostname(String host){return host;}};
        return new RestTransport(new DestinationPolicy(List.of("api.example.com")),RestTransportTest.tls,dns,host->RestTransportTest.server.getAddress().getPort()){
            @Override public JsonNode call(String base,RestOperation operation,JsonNode arguments,byte[] credential,UUID logical){assertThat(TransactionSynchronizationManager.isActualTransactionActive()).as("No database transaction spans provider I/O").isFalse();if(beforeCall!=null)beforeCall.run();var result=super.call(base,operation,arguments,credential,logical);if(afterCall!=null)afterCall.run();return result;}
        };
    }catch(Exception unavailable){throw new ExceptionInInitializerError(unavailable);}}
    static class MutableClock extends Clock {volatile Instant now=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return now;}void add(long seconds){now=now.plusSeconds(seconds);}}
    @TestConfiguration static class Configuration {
        @Bean @Primary RestTransport fixtureTransport(){return provider;}
        @Bean @Primary MutableClock fixtureClock(){return new MutableClock();}
        @Bean @Primary ExecutionRandom fixtureRandom(){return new ExecutionRandom(){@Override public double sample(){return 0;}};}
    }
    @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:77f585114c32fbca283dc835b0596f4e52b51b4c6662d7810b2f4084f60a1873").asCompatibleSubstituteFor("postgres")).withInitScript("organization-runtime.sql");
    @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",()->"bridgeops_app");r.add("spring.datasource.password",()->"synthetic-runtime-fixture");r.add("spring.flyway.user",postgres::getUsername);r.add("spring.flyway.password",postgres::getPassword);r.add("bridgeops.auth.private-key",()->keys.directory.resolve("private.pem").toString());r.add("bridgeops.auth.public-key",()->keys.directory.resolve("public.pem").toString());r.add("bridgeops.auth.csrf-key",()->keys.directory.resolve("csrf.key").toString());r.add("bridgeops.integrations.secrets.directory",()->keys.directory.toString());}
    @AfterAll static void cleanup()throws Exception{RestTransportTest.stop();Files.deleteIfExists(encryptionKey);keys.close();}
    @Autowired ExecutionRuntime runtime;@Autowired ExecutionStore store;@Autowired ExecutionService executions;@Autowired SyntheticCapability synthetic;@Autowired WorkflowService workflows;@Autowired GraphDefinition graphs;@Autowired ConnectionService connections;@Autowired AccountPasswords passwords;@Autowired PasswordSessionService sessions;@Autowired OrganizationService organizations;@Autowired ApprovalService approvals;@Autowired MutableClock clock;
    @Autowired ExternalDispatch external;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
    @Autowired com.bridgeops.integrations.application.AutomationConfiguration automations;@Autowired com.bridgeops.organizations.application.AutomationAuthority automationAuthority;@Autowired com.bridgeops.integrations.application.WebhookConfiguration endpoints;@Autowired com.bridgeops.integrations.application.WebhookIntake intake;
    JdbcTemplate operator;Actor owner;UUID org,workflow,version,connection;ExecutionWorker worker;static String passwordHash;
    record Actor(UUID id,UUID family){}
    @BeforeEach void fixture(){operator=new JdbcTemplate(new DriverManagerDataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()));operator.execute("TRUNCATE users,installation_state,authentication_throttles CASCADE");operator.update("INSERT INTO installation_state(singleton_id) VALUES(1)");clock.now=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);requests.set(0);status=0;retryAfter=null;drop=false;beforeCall=null;afterCall=null;receivedAuthorization=null;receivedKey=null;receivedBody=null;if(passwordHash==null)passwordHash=passwords.hash("rest-workflow-disposable-password");owner=account("owner@example.invalid");operator.update("INSERT INTO user_grants VALUES(?,'organization.create',?)",owner.id(),java.sql.Timestamp.from(clock.instant()));org=organizations.create(owner.id(),owner.family(),"REST fixture","rest-fixture").id();worker=new ExecutionWorker(runtime,synthetic,4,2,30,1000);}
    Actor account(String email){UUID id=UUID.randomUUID();var at=java.sql.Timestamp.from(clock.instant());operator.update("INSERT INTO users(id,email,normalized_email,password_hash,display_name,account_status,created_at,email_verified_at) VALUES(?,?,?,?,?,'ACTIVE',?,?)",id,email,email,passwordHash,"Synthetic REST actor",at,at);var grant=(Granted)sessions.authenticate(email,"rest-workflow-disposable-password");return new Actor(id,grant.familyId());}
    Actor reviewer(){var actor=account("approver@example.invalid");UUID membership=UUID.randomUUID();operator.update("INSERT INTO organization_memberships(id,organization_id,user_id,status,joined_at) VALUES(?,?,?,'ACTIVE',?)",membership,org,actor.id(),java.sql.Timestamp.from(clock.instant()));operator.update("INSERT INTO membership_roles SELECT ?,?,id FROM roles WHERE organization_id=? AND name='APPROVER'",org,membership,org);return actor;}
    void publish(boolean write,String credential){
        String config="{\"baseDestination\":\"https://api.example.com\",\"healthOperation\":null,\"operations\":[{\"id\":\"operation\",\"method\":\""+(write?"POST":"GET")+"\",\"path\":\"/workflow\",\"pathParameters\":[],\"requestFields\":"+(write?"{\"message\":\"STRING\"}":"{}")+",\"responseFields\":{\"message\":\"STRING\"},\"classification\":\""+(write?"WRITE":"READ")+"\",\"timeoutSeconds\":3,\"maximumResponseBytes\":4096,\"remoteIdempotencyKey\":true}]}";
        connection=connections.create(owner.id(),owner.family(),org,"Controlled provider","","REST",graphs.parse(config),credential).connection().id();
        String graph="{\"schemaVersion\":2,\"nodes\":[{\"id\":\"start\",\"type\":\"manualTrigger\",\"typeVersion\":1,\"config\":{\"inputFields\":{}},\"inputs\":{}},{\"id\":\"http\",\"type\":\"configuredHttp\",\"typeVersion\":1,\"config\":{\"integrationId\":\""+connection+"\",\"revision\":0,\"operation\":\"operation\"},\"inputs\":{\"pathParameters\":{\"literal\":{}},\"fields\":{\"literal\":"+(write?"{\"message\":\"Approved payload\"}":"{}")+"}}},{\"id\":\"end\",\"type\":\"end\",\"typeVersion\":1,\"config\":{},\"inputs\":{}}],\"edges\":[{\"source\":\"start\",\"target\":\"http\"},{\"source\":\"http\",\"target\":\"end\"}]}";
        assertThat(graphs.validate(graphs.parse(graph)).valid()).isTrue();workflow=workflows.create(owner.id(),owner.family(),org,"Controlled HTTP workflow","",graphs.parse(graph)).workflow().id();version=workflows.publish(owner.id(),owner.family(),org,workflow,0).version().id();
    }
    UUID start(){return executions.start(owner.id(),owner.family(),org,workflow,version,graphs.parse("{}"),0,"rest-"+UUID.randomUUID(),true).execution().id();}
    void drain(){for(int i=0;i<100;i++){runtime.reconcile();var claim=runtime.claim(UUID.randomUUID(),4,2,30);if(claim==null)return;worker.dispatch(claim);}throw new AssertionError("Bounded REST fixture did not reach a durable checkpoint.");}
    void approve(UUID execution,Actor reviewer){var request=approvals.list(reviewer.id(),reviewer.family(),org,0,25,"PENDING",execution).items().getFirst();assertThat(request.capability()).isEqualTo("rest");assertThat(request.arguments().path("fields").path("message").asString()).isEqualTo("Approved payload");assertThatThrownBy(()->approvals.decide(owner.id(),owner.family(),org,request.id(),0,"APPROVE",null)).isInstanceOfSatisfying(DomainFailure.class,e->assertThat(e.status()).isEqualTo(403));approvals.decide(reviewer.id(),reviewer.family(),org,request.id(),0,"APPROVE","Reviewed exact provider payload");}
    long count(String table){return operator.queryForObject("SELECT count(*) FROM "+table,Long.class);}
    ExecutionRuntime.Dispatch readyRead(){var first=runtime.claim(UUID.randomUUID(),4,2,30);assertThat(first).isNotNull();worker.dispatch(first);var claim=runtime.claim(UUID.randomUUID(),4,2,30);assertThat(claim).isNotNull();var task=runtime.prepare(claim);assertThat(task.node().id()).isEqualTo("http");return task;}
    UUID signedWrite()throws Exception{
        publish(true,null);var definition=(tools.jackson.databind.node.ObjectNode)workflows.version(owner.id(),owner.family(),org,workflow,version).definition();for(var node:definition.path("nodes"))if(node.path("id").asString().equals("start"))((tools.jackson.databind.node.ObjectNode)node).put("type","webhookTrigger");assertThat(graphs.validate(definition).valid()).isTrue();workflow=workflows.create(owner.id(),owner.family(),org,"Signed REST fixture","",definition).workflow().id();version=workflows.publish(owner.id(),owner.family(),org,workflow,0).version().id();var principal=automations.create(owner.id(),owner.family(),org,"Exact REST authority",workflow,version);var endpoint=endpoints.create(owner.id(),owner.family(),org,"Controlled REST delivery",principal.id(),true);byte[] key=Base64.getUrlDecoder().decode(endpoint.signingSecret()),body="{\"input\":{}}".getBytes(StandardCharsets.UTF_8);String timestamp=Long.toString(clock.instant().getEpochSecond());String signature;
        try{var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(key,"HmacSHA256"));mac.update(("v1\n"+timestamp+"\ncontrolled-rest\n").getBytes(StandardCharsets.UTF_8));signature=HexFormat.of().formatHex(mac.doFinal(body));}finally{Arrays.fill(key,(byte)0);}return intake.receive(endpoint.endpoint().id(),timestamp,"controlled-rest",signature,body).execution();
    }
    @Test void alteredDispatchActorAndForgedObservationCannotAuthorizeAnExternalCall(){publish(false,null);UUID id=start();var task=readyRead();var forged=new ExecutionRuntime.Dispatch(task.claim(),task.node(),UUID.randomUUID(),task.operation(),task.requester());assertThatThrownBy(()->runtime.executeExternal(forged)).isInstanceOfSatisfying(DomainFailure.class,e->assertThat(e.code()).isEqualTo("OPERATION_INTENT_MISMATCH"));assertThat(requests.get()).isZero();assertThat(count("integration_outbound_dispatches")).isZero();var work=new CapabilityDispatch.Work(org,id,task.claim().owner(),task.claim().token(),Set.of(owner.id()),task.requester());var badWork=new CapabilityDispatch.Work(org,id,UUID.randomUUID(),task.claim().token()+1,Set.of(owner.id()),task.requester());assertThatThrownBy(()->external.execute(badWork,"http")).isInstanceOf(DomainFailure.class);assertThat(requests.get()).isZero();var observed=runtime.executeExternal(task);assertThatThrownBy(()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(tx->external.finish(work,"http",new ExternalDispatch.Observation(){}))).isInstanceOf(DomainFailure.class);assertThat(count("integration_outbound_outcomes")).isZero();assertThat(runtime.complete(task,observed)).isTrue();runtime.acknowledge(task.claim());drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(1);}
    @Test void exactLargeIntegerArgumentsArePreservedThroughHumanReviewAndTheProviderBody(){
        publish(true,null);var managed=connections.configuration(owner.id(),owner.family(),org,connection);var config=(tools.jackson.databind.node.ObjectNode)managed.configuration();((tools.jackson.databind.node.ObjectNode)config.path("operations").get(0)).putObject("requestFields").put("amount","INTEGER");connections.update(owner.id(),owner.family(),org,connection,0,"Exact integer provider","",true,config,null,false);
        var definition=(tools.jackson.databind.node.ObjectNode)workflows.version(owner.id(),owner.family(),org,workflow,version).definition();for(var node:definition.path("nodes"))if(node.path("id").asString().equals("http")){((tools.jackson.databind.node.ObjectNode)node.path("config")).put("revision",1);((tools.jackson.databind.node.ObjectNode)node.path("inputs").path("fields")).putObject("literal").put("amount",Long.MAX_VALUE);}
        workflow=workflows.create(owner.id(),owner.family(),org,"Exact numeric approval","",definition).workflow().id();version=workflows.publish(owner.id(),owner.family(),org,workflow,0).version().id();var reviewer=reviewer();UUID id=start();drain();var request=approvals.list(reviewer.id(),reviewer.family(),org,0,25,"PENDING",id).items().getFirst();var detail=approvals.get(reviewer.id(),reviewer.family(),org,request.id());assertThat(detail.canonicalArguments()).contains("9223372036854775807");assertThat(detail.argumentHash()).isEqualTo(com.bridgeops.executions.domain.ExecutionPlan.hash(detail.canonicalArguments()));assertThat(detail.arguments().path("fields").path("amount").bigIntegerValue()).isEqualTo(java.math.BigInteger.valueOf(Long.MAX_VALUE));approvals.decide(reviewer.id(),reviewer.family(),org,detail.id(),0,"APPROVE","Reviewed exact integer value");drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(receivedBody).contains("9223372036854775807");assertThat(requests.get()).isEqualTo(1);
    }
    @Test void staleWorkerCannotCommitAProviderObservationAfterANewerFence(){publish(false,null);UUID id=start();var old=readyRead();var observed=runtime.executeExternal(old);assertThat(requests.get()).isEqualTo(1);clock.add(31);runtime.reconcile();assertThat(runtime.complete(old,observed)).isFalse();assertThat(count("integration_outbound_outcomes")).isZero();assertThat(count("integration_operation_receipts")).isZero();drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(2);assertThat(count("integration_operation_receipts")).isEqualTo(1);assertThat(runtime.complete(old,observed)).isFalse();assertThat(requests.get()).isEqualTo(2);}
    @Test void disablingAConnectionAfterApprovalPreventsDispatch(){publish(true,null);var reviewer=reviewer();UUID id=start();drain();approve(id,reviewer);var managed=connections.configuration(owner.id(),owner.family(),org,connection);connections.update(owner.id(),owner.family(),org,connection,0,"Disabled provider","",false,managed.configuration(),null,false);drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("FAILED");assertThat(requests.get()).isZero();assertThat(count("integration_outbound_dispatches")).isZero();assertThat(count("integration_operation_receipts")).isZero();}
    @Test void signedAutomationUsesItsExactRestGrantAndARealIndependentApprover()throws Exception{UUID id=signedWrite();var reviewer=reviewer();drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("WAITING_FOR_APPROVAL");assertThat(store.get(org,id,false).actor()).isNull();assertThat(requests.get()).isZero();approve(id,reviewer);sessions.revokeFamily(owner.id(),owner.family());drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(1);assertThat(count("users")).isEqualTo(2);assertThat(operator.queryForObject("SELECT count(*) FROM organization_audit_events WHERE action IN ('OUTBOUND_DISPATCHED','OUTBOUND_RESULT_RECORDED') AND actor_type='AUTOMATION' AND actor_id IS NULL",Long.class)).isEqualTo(2);}
    @Test void revokedAutomationCannotUseAnAlreadyApprovedRestOperation()throws Exception{UUID id=signedWrite();var reviewer=reviewer();drain();approve(id,reviewer);var e=store.get(org,id,false);automationAuthority.revoke(owner.id(),owner.family(),org,e.automation().principal(),0);drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("FAILED");assertThat(requests.get()).isZero();assertThat(count("integration_outbound_dispatches")).isZero();assertThat(count("integration_operation_receipts")).isZero();}
    @AfterEach void removeAuditSeam(){operator.execute("DROP TRIGGER IF EXISTS test_rest_audit ON organization_audit_events");}
    void failAudit(String action){assertThat(Set.of("OUTBOUND_DISPATCHED","OUTBOUND_RESULT_RECORDED")).contains(action);operator.execute("CREATE OR REPLACE FUNCTION test_rest_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='"+action+"' THEN RAISE EXCEPTION 'Controlled outbound audit failure'; END IF; RETURN NEW; END $$");operator.execute("CREATE TRIGGER test_rest_audit BEFORE INSERT ON organization_audit_events FOR EACH ROW EXECUTE FUNCTION test_rest_audit_failure()");}
    @Test void crashAfterCommittedDispatchBeforeSendNeverBlindlyRepeatsAWrite(){publish(true,null);var reviewer=reviewer();UUID id=start();drain();approve(id,reviewer);beforeCall=()->{beforeCall=null;throw new IllegalStateException("Controlled interruption before provider call");};drain();assertThat(requests.get()).isZero();assertThat(count("integration_outbound_dispatches")).isEqualTo(1);assertThat(count("integration_outbound_outcomes")).isZero();clock.add(31);drain();assertThat(store.get(org,id,false).error()).isEqualTo("RECONCILIATION_REQUIRED");assertThat(requests.get()).isZero();assertThat(count("integration_operation_receipts")).isZero();}
    @Test void crashAfterProviderWriteBeforeResultCommitRequiresReconciliation(){publish(true,null);var reviewer=reviewer();UUID id=start();drain();approve(id,reviewer);afterCall=()->{afterCall=null;throw new IllegalStateException("Controlled interruption after provider response");};drain();assertThat(requests.get()).isEqualTo(1);assertThat(count("integration_outbound_outcomes")).isZero();assertThat(count("integration_operation_receipts")).isZero();clock.add(31);drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("FAILED");assertThat(store.get(org,id,false).error()).isEqualTo("RECONCILIATION_REQUIRED");assertThat(requests.get()).isEqualTo(1);assertThat(count("integration_outbound_dispatches")).isEqualTo(1);}
    @Test void interruptedReadMayRecoverWithANewFenceAndOneLogicalReceipt(){publish(false,null);UUID id=start();afterCall=()->{afterCall=null;throw new IllegalStateException("Controlled read interruption");};drain();assertThat(requests.get()).isEqualTo(1);clock.add(31);drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(2);assertThat(count("integration_operation_receipts")).isEqualTo(1);assertThat(count("integration_outbound_dispatches")).isEqualTo(2);assertThat(count("integration_outbound_outcomes")).isEqualTo(1);}
    @Test void preDispatchAuditFailureRollsBackTheMarkerAndPreventsTheRequest(){publish(true,null);var reviewer=reviewer();UUID id=start();drain();approve(id,reviewer);failAudit("OUTBOUND_DISPATCHED");drain();assertThat(requests.get()).isZero();assertThat(count("integration_outbound_dispatches")).isZero();operator.execute("DROP TRIGGER test_rest_audit ON organization_audit_events");clock.add(31);drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(1);}
    @Test void resultAuditFailureRollsBackReceiptAndStepButCannotUndoTheProviderWrite(){publish(true,null);var reviewer=reviewer();UUID id=start();drain();approve(id,reviewer);failAudit("OUTBOUND_RESULT_RECORDED");drain();assertThat(requests.get()).isEqualTo(1);assertThat(count("integration_outbound_dispatches")).isEqualTo(1);assertThat(count("integration_outbound_outcomes")).isZero();assertThat(count("integration_operation_receipts")).isZero();operator.execute("DROP TRIGGER test_rest_audit ON organization_audit_events");clock.add(31);drain();assertThat(store.get(org,id,false).error()).isEqualTo("RECONCILIATION_REQUIRED");assertThat(requests.get()).isEqualTo(1);}
    @Test void cancellationDuringAnAlreadyDispatchedCallRetainsUnknownEvidenceWithoutResuming(){publish(true,null);var reviewer=reviewer();UUID id=start();drain();approve(id,reviewer);beforeCall=()->{beforeCall=null;var execution=store.get(org,id,false);executions.cancel(owner.id(),owner.family(),org,id,execution.revision(),"Cancel after dispatch checkpoint");};drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("CANCELLED");assertThat(requests.get()).isEqualTo(1);assertThat(count("integration_outbound_dispatches")).isEqualTo(1);assertThat(count("integration_outbound_outcomes")).isZero();assertThat(count("integration_operation_receipts")).isZero();clock.add(60);drain();assertThat(requests.get()).isEqualTo(1);assertThat(store.get(org,id,false).state().name()).isEqualTo("CANCELLED");}
    @Test void deadlineDuringProviderCallNeverCommitsALateSuccess(){publish(false,null);UUID id=start();Instant deadline=store.get(org,id,false).deadline();beforeCall=()->{beforeCall=null;clock.now=deadline;};drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("FAILED");assertThat(store.get(org,id,false).error()).isEqualTo("DEADLINE_EXCEEDED");assertThat(requests.get()).isEqualTo(1);assertThat(count("integration_outbound_outcomes")).isZero();assertThat(count("integration_operation_receipts")).isZero();}
    @Test void providerRetryAfterIsPersistedAndConsumesTheSameDeadline(){publish(false,null);status=429;retryAfter="45";UUID id=start();Instant deadline=store.get(org,id,false).deadline();drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("WAITING_FOR_RETRY");assertThat(operator.queryForObject("SELECT due_at FROM execution_work_items WHERE execution_id=?",java.sql.Timestamp.class,id).toInstant()).isEqualTo(clock.instant().plusSeconds(45));clock.add(44);drain();assertThat(requests.get()).isEqualTo(1);clock.add(1);status=200;drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(2);assertThat(store.get(org,id,false).deadline()).isEqualTo(deadline);}
    @Test void realTlsReadCommitsProjectedReceiptAndAttemptWithoutHoldingATransaction(){publish(false,null);UUID id=start();drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(1);assertThat(count("integration_outbound_dispatches")).isEqualTo(1);assertThat(count("integration_outbound_outcomes")).isEqualTo(1);assertThat(count("integration_operation_receipts")).isEqualTo(1);assertThat(store.steps(org,id).stream().filter(s->s.node().equals("http")).findFirst().orElseThrow().output()).isEqualTo("{\"response\":{\"message\":\"controlled-result\"}}");assertThat(operator.queryForObject("SELECT result_json FROM integration_operation_receipts",String.class)).doesNotContain("ignoredSecret","not-projected");}
    @Test void configuredWriteRequiresExactDistinctHumanApprovalEvenWithPolicyOff(){publish(true,"disposable-provider-credential");var reviewer=reviewer();UUID id=start();drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("WAITING_FOR_APPROVAL");assertThat(requests.get()).isZero();approve(id,reviewer);drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(1);assertThat(receivedAuthorization).isEqualTo("Bearer disposable-provider-credential");assertThat(graphs.parse(receivedBody).path("message").asString()).isEqualTo("Approved payload");assertThat(receivedKey).isEqualTo(store.steps(org,id).stream().filter(s->s.node().equals("http")).findFirst().orElseThrow().operation().toString());assertThat(operator.queryForObject("SELECT result_json FROM integration_operation_receipts",String.class)).doesNotContain("disposable-provider-credential");}
    @Test void readTransientFailureSchedulesThenRetriesTheSameLogicalOperation(){publish(false,null);status=503;UUID id=start();drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("WAITING_FOR_RETRY");assertThat(requests.get()).isEqualTo(1);status=200;clock.add(60);drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("SUCCEEDED");assertThat(requests.get()).isEqualTo(2);assertThat(count("integration_outbound_dispatches")).isEqualTo(2);assertThat(count("integration_operation_receipts")).isEqualTo(1);}
    @Test void lostWriteResponseFailsForReconciliationWithoutAnotherRequest(){publish(true,null);var reviewer=reviewer();UUID id=start();drain();approve(id,reviewer);drop=true;drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("FAILED");assertThat(store.get(org,id,false).error()).isEqualTo("RECONCILIATION_REQUIRED");assertThat(requests.get()).isEqualTo(1);clock.add(120);drain();assertThat(requests.get()).isEqualTo(1);assertThat(count("integration_operation_receipts")).isZero();assertThat(operator.queryForObject("SELECT outcome FROM integration_outbound_outcomes",String.class)).isEqualTo("RECONCILIATION_REQUIRED");}
    @Test void providerPermissionFailureIsPermanentAndEarlierProgressRemainsVisible(){publish(false,null);status=403;UUID id=start();drain();assertThat(store.get(org,id,false).state().name()).isEqualTo("FAILED");assertThat(requests.get()).isEqualTo(1);assertThat(store.steps(org,id).stream().filter(s->s.node().equals("start")).findFirst().orElseThrow().state()).isEqualTo("SUCCEEDED");clock.add(120);drain();assertThat(requests.get()).isEqualTo(1);}
    @Test void repeatedTransientReadStopsAtThreeAttemptsAndNeverResetsDeadline(){publish(false,null);status=503;UUID id=start();Instant deadline=store.get(org,id,false).deadline();for(int i=0;i<3;i++){drain();clock.add(60);}assertThat(store.get(org,id,false).state().name()).isEqualTo("FAILED");assertThat(store.get(org,id,false).error()).isEqualTo("TRANSIENT_EXHAUSTED");assertThat(store.get(org,id,false).deadline()).isEqualTo(deadline);assertThat(requests.get()).isEqualTo(3);assertThat(count("integration_outbound_dispatches")).isEqualTo(3);}
}
